/* Jepun Quiz — vanilla JavaScript, no framework or online dependency.
   When hosted over HTTP, JSON files are loaded from ./data/.
   For double-click/file:// access, an embedded snapshot is used instead. */
(() => {
  'use strict';
  const FILES = ['hiragana', 'katakana', 'N5', 'N4', 'N3', 'vocabulary_N5', 'vocabulary_N4', 'vocabulary_N3'];
  const SIZES = { short: 16, medium: 24, long: 32 };
  const STORAGE_KEY = 'jepun-quiz-local-v1';
  const LEVELS = [
    { key: 'hiragana', name: 'Hiragana', category: 'kanji', symbol: 'あ', color: 'hiragana' },
    { key: 'katakana', name: 'Katakana', category: 'kanji', symbol: 'ア', color: 'katakana' },
    { key: 'N5', name: 'JLPT N5', category: 'kanji', symbol: '五', color: 'n5' },
    { key: 'N4', name: 'JLPT N4', category: 'kanji', symbol: '四', color: 'n4' },
    { key: 'N3', name: 'JLPT N3', category: 'kanji', symbol: '三', color: 'n3' },
    { key: 'N2', name: 'JLPT N2', category: 'kanji', symbol: '二', color: 'n2', locked: true },
    { key: 'N1', name: 'JLPT N1', category: 'kanji', symbol: '一', color: 'n1', locked: true },
    { key: 'vocabulary_N5', name: 'Vocabulary N5', category: 'vocabulary', symbol: '語', color: 'n5' },
    { key: 'vocabulary_N4', name: 'Vocabulary N4', category: 'vocabulary', symbol: '語', color: 'n4' },
    { key: 'vocabulary_N3', name: 'Vocabulary N3', category: 'vocabulary', symbol: '語', color: 'n3' },
    { key: 'vocabulary_N2', name: 'Vocabulary N2', category: 'vocabulary', symbol: '語', color: 'n2', locked: true },
    { key: 'vocabulary_N1', name: 'Vocabulary N1', category: 'vocabulary', symbol: '語', color: 'n1', locked: true },
  ];
  const byId = id => document.getElementById(id);
  const el = {
    openLevels: byId('openLevels'), levelOverlay: byId('levelOverlay'), closeLevels: byId('closeLevels'),
    levelListView: byId('levelListView'), groupListView: byId('groupListView'), levelList: byId('levelList'),
    groupGrid: byId('groupGrid'), backToLevels: byId('backToLevels'),
    selectedLevelIcon: byId('selectedLevelIcon'), selectedLevelName: byId('selectedLevelName'),
    selectedLevelSubtitle: byId('selectedLevelSubtitle'), selectedProgressRing: byId('selectedProgressRing'),
    selectedProgressPct: byId('selectedProgressPct'), categoryTabs: byId('categoryTabs'), sizeTabs: byId('sizeTabs'),
    randomQuiz: byId('randomQuiz'), weakQuiz: byId('weakQuiz'), resetProgress: byId('resetProgress'),
    questionCard: byId('questionCard'), questionFace: byId('questionFace'), questionReading: byId('questionReading'),
    questionText: byId('questionText'), promptHelper: byId('promptHelper'), questionDetails: byId('questionDetails'),
    meaningList: byId('meaningList'), questionGroup: byId('questionGroup'), questionNumber: byId('questionNumber'),
    correctCount: byId('correctCount'), incorrectCount: byId('incorrectCount'), remainingCount: byId('remainingCount'),
    answerGrid: byId('answerGrid'), swipeTip: byId('swipeTip'), nextButton: byId('nextButton'),
    resultsOverlay: byId('resultsOverlay'), resultHead: byId('resultHead'), resultHeading: byId('resultHeading'),
    resultScore: byId('resultScore'), resultGroupName: byId('resultGroupName'), resultLevelLabel: byId('resultLevelLabel'),
    resultLevelPercent: byId('resultLevelPercent'), resultDelta: byId('resultDelta'), resultProgressBar: byId('resultProgressBar'),
    nextGroupButton: byId('nextGroupButton'), restartButton: byId('restartButton'), retryButton: byId('retryButton'),
    randomAgainButton: byId('randomAgainButton'), chooseLevelButton: byId('chooseLevelButton'), toast: byId('toast'),
  };
  const data = {};
  let saved = readSaved();
  let activeLevelKey = saved.settings?.levelKey || 'vocabulary_N5';
  let quizSize = SIZES[saved.settings?.size] ? saved.settings.size : 'short';
  let promptMode = ['kanji', 'kana', 'english'].includes(saved.settings?.promptMode) ? saved.settings.promptMode : 'kanji';
  let answerMode = ['kana', 'english'].includes(saved.settings?.answerMode) ? saved.settings.answerMode : 'english';
  let drawerCategory = 'kanji';
  let drawerLevelKey = null;
  let session = null;
  let answered = false;
  let chosenId = null;
  let options = [];
  let toastTimer;

  function readSaved() {
    try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || {}; } catch { return {}; }
  }
  function save() {
    saved.settings = { levelKey: activeLevelKey, size: quizSize, promptMode, answerMode };
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(saved)); } catch { /* storage optional */ }
  }
  function progressFor(key) {
    saved.progress ||= {};
    return (saved.progress[key] ||= { best: {}, mistakes: {} });
  }
  function getLevel(key) { return LEVELS.find(l => l.key === key); }
  function groupCount(key = activeLevelKey) { return Math.ceil((data[key]?.length || 0) / SIZES[quizSize]); }
  function groupProgress(key, num) { return progressFor(key).best[`${quizSize}:${num}`] || 0; }
  function levelProgress(key) {
    const groups = groupCount(key);
    if (!groups) return 0;
    let sum = 0;
    for (let g = 1; g <= groups; g++) sum += groupProgress(key, g);
    return Math.round(sum / groups);
  }
  function groupsStudied(key) {
    let studied = 0;
    for (let g = 1; g <= groupCount(key); g++) if (groupProgress(key, g) > 0 || progressFor(key).best[`${quizSize}:${g}`] === 0 && Object.prototype.hasOwnProperty.call(progressFor(key).best, `${quizSize}:${g}`)) studied++;
    return studied;
  }
  const shuffle = arr => {
    const result = [...arr];
    for (let i = result.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [result[i], result[j]] = [result[j], result[i]]; }
    return result;
  };
  const clamp = (n, min, max) => Math.max(min, Math.min(max, n));
  const pct = (n, d) => d ? Math.round(n / d * 100) : 0;
  function levelName(key) { return getLevel(key)?.name || 'Japanese Quiz'; }
  function displayLabel() {
    if (!session) return '';
    if (session.mode === 'group') return `${levelName(session.key)} Group ${session.group}`;
    if (session.mode === 'random') return `${levelName(session.key)} · Random Quiz`;
    if (session.mode === 'weak') return `${levelName(session.key)} · Review Weakest`;
    return `${levelName(session.key)} · Retry Incorrect`;
  }
  function activeItem() { return session?.items[session.index]; }
  function notify(message) {
    clearTimeout(toastTimer);
    el.toast.textContent = message;
    el.toast.classList.add('visible');
    toastTimer = setTimeout(() => el.toast.classList.remove('visible'), 2300);
  }

  async function loadData() {
    if (location.protocol === 'file:') {
      Object.assign(data, EMBEDDED_DATA);
      return;
    }
    await Promise.all(FILES.map(async name => {
      try {
        const response = await fetch(`data/${name}.json`, { cache: 'no-cache' });
        if (!response.ok) throw Error(`HTTP ${response.status}`);
        const records = await response.json();
        if (!Array.isArray(records)) throw Error('JSON must contain an array');
        data[name] = records.filter(record => record && record.id && record.kana && record.english && record.kanji);
      } catch (error) {
        console.warn(`Tidak dapat membaca data/${name}.json; menggunakan data cadangan`, error);
        data[name] = EMBEDDED_DATA[name];
      }
    }));
  }

  function openDrawer(category = null, key = null) {
    const level = getLevel(activeLevelKey);
    drawerCategory = category || level?.category || 'kanji';
    drawerLevelKey = key;
    renderDrawer();
    el.levelOverlay.hidden = false;
    document.body.style.overflow = 'hidden';
    document.querySelector('.level-panel').focus();
  }
  function closeDrawer() {
    el.levelOverlay.hidden = true;
    document.body.style.overflow = '';
    el.openLevels.focus();
  }
  function renderDrawer() {
    el.categoryTabs.querySelectorAll('[data-category]').forEach(button => {
      const active = button.dataset.category === drawerCategory;
      button.classList.toggle('active', active);
      button.setAttribute('aria-selected', String(active));
    });
    el.levelListView.hidden = Boolean(drawerLevelKey);
    el.groupListView.hidden = !drawerLevelKey;
    if (drawerLevelKey) renderGroups(); else renderLevels();
  }
  function renderLevels() {
    el.levelList.replaceChildren();
    const selection = LEVELS.filter(level => level.category === drawerCategory);
    for (const level of selection) {
      const row = document.createElement('button');
      row.type = 'button'; row.className = 'level-row'; row.disabled = Boolean(level.locked);
      const icon = document.createElement('span'); icon.className = `level-icon ${level.color}`; icon.textContent = level.symbol;
      const meta = document.createElement('span'); meta.className = 'level-meta';
      const title = document.createElement('strong'); title.textContent = level.name;
      const caption = document.createElement('small');
      caption.textContent = level.locked ? 'Data belum tersedia' : `${groupCount(level.key)} quizzes${groupsStudied(level.key) ? ` · ${groupsStudied(level.key)} studied` : ''}`;
      meta.append(title, caption);
      const indicator = document.createElement('span');
      if (level.locked) { indicator.className = 'level-lock'; indicator.textContent = '🔒'; }
      else { indicator.className = 'ring'; const percent = levelProgress(level.key); indicator.style.setProperty('--percent', percent); const percentSpan = document.createElement('span'); percentSpan.textContent = `${percent}%`; indicator.append(percentSpan); }
      const arrow = document.createElement('span'); arrow.className = 'level-arrow'; arrow.textContent = '›';
      row.append(icon, meta, indicator, arrow);
      if (!level.locked) row.addEventListener('click', () => { drawerLevelKey = level.key; renderDrawer(); });
      el.levelList.append(row);
    }
  }
  function renderGroups() {
    const level = getLevel(drawerLevelKey); if (!level) return;
    const completed = groupsStudied(level.key);
    const total = groupCount(level.key);
    const value = levelProgress(level.key);
    el.selectedLevelName.textContent = level.name;
    el.selectedLevelSubtitle.textContent = `${completed} of ${total} quizzes studied`;
    el.selectedLevelIcon.className = `selected-icon ${level.color}`;
    el.selectedLevelIcon.textContent = level.symbol;
    el.selectedProgressPct.textContent = `${value}%`;
    el.selectedProgressRing.style.setProperty('--percent', value);
    el.sizeTabs.querySelectorAll('[data-size]').forEach(button => button.classList.toggle('active', button.dataset.size === quizSize));
    el.groupGrid.replaceChildren();
    for (let group = 1; group <= total; group++) {
      const score = groupProgress(level.key, group);
      const tile = document.createElement('button'); tile.type = 'button'; tile.className = 'group-tile';
      if (Object.prototype.hasOwnProperty.call(progressFor(level.key).best, `${quizSize}:${group}`)) tile.classList.add('studied');
      const number = document.createElement('strong'); number.textContent = group;
      const scoreCaption = document.createElement('small'); scoreCaption.textContent = `${score}%`;
      tile.append(number, scoreCaption);
      tile.title = `${level.name} · Group ${group}`;
      tile.addEventListener('click', () => beginQuiz({ key: level.key, mode: 'group', group }));
      el.groupGrid.append(tile);
    }
  }
  function changePromptMode(mode) {
    promptMode = mode;
    if (promptMode === 'english' && answerMode === 'english') answerMode = 'kana';
    if (promptMode === 'kana' && answerMode === 'kana') answerMode = 'english';
    // Kana-only characters have no separate kanji representation.
    if (promptMode === 'kanji' && answerMode === 'kana' && ['hiragana','katakana'].includes(session?.key)) answerMode = 'english';
    save(); renderModeButtons(); renderQuestion(); renderOptions();
  }
  function changeAnswerMode(mode) {
    answerMode = mode;
    if (answerMode === 'english' && promptMode === 'english') promptMode = 'kanji';
    if (answerMode === 'kana' && (promptMode === 'kana' || (promptMode === 'kanji' && ['hiragana', 'katakana'].includes(session?.key)))) promptMode = 'english';
    save(); renderModeButtons(); renderQuestion(); renderOptions();
  }
  function renderModeButtons() {
    document.querySelectorAll('[data-prompt-mode]').forEach(b => { const active = b.dataset.promptMode === promptMode; b.classList.toggle('active', active); b.setAttribute('aria-pressed', String(active)); });
    document.querySelectorAll('[data-answer-mode]').forEach(b => { const active = b.dataset.answerMode === answerMode; b.classList.toggle('active', active); b.setAttribute('aria-pressed', String(active)); });
  }
  function beginQuiz({ key, mode = 'group', group = 1, customItems = null }) {
    const level = getLevel(key);
    if (!level || level.locked || !data[key]?.length) { notify('Data level belum tersedia.'); return; }
    activeLevelKey = key;
    let items;
    if (customItems) items = [...customItems];
    else if (mode === 'group') items = shuffle(data[key].slice((group - 1) * SIZES[quizSize], group * SIZES[quizSize])); // Soal dalam grup tetap, urutan diacak pada setiap mulai/restart.
    else if (mode === 'weak') {
      const mistakes = progressFor(key).mistakes;
      const byMistake = data[key].filter(item => (mistakes[item.id] || 0) > 0).sort((a, b) => (mistakes[b.id] || 0) - (mistakes[a.id] || 0));
      const first = byMistake.slice(0, SIZES[quizSize]);
      const rest = shuffle(data[key].filter(item => !first.includes(item))).slice(0, SIZES[quizSize] - first.length);
      items = shuffle([...first, ...rest]);
      if (!byMistake.length) notify('Belum ada kesalahan tersimpan. Memulai kuis acak.');
    } else items = shuffle(data[key]).slice(0, SIZES[quizSize]);
    if (!items.length) { notify('Grup ini kosong.'); return; }
    session = { key, mode, group, items, index: 0, correct: 0, incorrect: 0, missed: [] };
    if (['hiragana','katakana'].includes(key) && answerMode === 'kana') answerMode = 'english';
    if (promptMode === answerMode) changePromptMode(answerMode === 'english' ? 'kanji' : 'english');
    save();
    el.resultsOverlay.hidden = true;
    if (!el.levelOverlay.hidden) closeDrawer();
    loadQuestion();
  }
  function updateCounters() {
    if (!session) return;
    el.correctCount.textContent = session.correct;
    el.incorrectCount.textContent = session.incorrect;
    el.remainingCount.textContent = session.items.length - session.index - (answered ? 1 : 0);
  }
  function getOptions(item) {
    const same = data[session.key];
    const usedKana = new Set([item.kana.trim().toLowerCase()]);
    const usedEnglish = new Set([item.english.trim().toLowerCase()]);
    const distractors = [];
    for (const candidate of shuffle(same)) {
      if (candidate.id === item.id) continue;
      const kana = candidate.kana.trim().toLowerCase(), english = candidate.english.trim().toLowerCase();
      if (usedKana.has(kana) || usedEnglish.has(english)) continue;
      usedKana.add(kana); usedEnglish.add(english); distractors.push(candidate);
      if (distractors.length >= 8) break;
    }
    return shuffle([item, ...distractors]);
  }
  function loadQuestion() {
    answered = false; chosenId = null;
    const item = activeItem(); if (!item) return;
    options = getOptions(item);
    el.questionCard.classList.remove('revealed');
    el.questionDetails.hidden = true;
    el.meaningList.replaceChildren();
    el.questionGroup.textContent = displayLabel();
    el.questionNumber.textContent = `${session.index + 1} of ${session.items.length}`;
    el.nextButton.disabled = true;
    el.swipeTip.textContent = 'Pilih jawaban yang benar';
    updateCounters(); renderModeButtons(); renderQuestion(); renderOptions();
  }
  function renderQuestion() {
    const item = activeItem(); if (!item) return;
    const isKanaOnly = ['hiragana','katakana'].includes(session.key);
    let main, reading = '', helper = '';
    if (promptMode === 'english') { main = item.english; helper = 'What is the Japanese?'; }
    else if (promptMode === 'kana') { main = item.kana; helper = ''; }
    else { main = item.kanji || item.kana; if (!isKanaOnly && item.kana !== item.kanji) reading = item.kana; }
    el.questionText.textContent = main;
    el.questionText.classList.toggle('long-text', main.length > 11 || (promptMode === 'english' && main.length > 18));
    // Sembunyikan bacaan kana pada soal Kanji sampai pengguna menjawab.
    // Mode Kana dan English tidak membutuhkan furigana terpisah.
    el.questionReading.textContent = answered ? reading : '';
    el.questionReading.hidden = !answered || !reading;
    el.promptHelper.textContent = helper;
  }
  function renderOptions() {
    if (!session) return;
    const correct = activeItem();
    el.answerGrid.replaceChildren();
    options.forEach((item, index) => {
      const button = document.createElement('button');
      button.type = 'button'; button.className = 'answer-card';
      button.setAttribute('aria-label', `Jawaban ${index + 1}: ${answerMode === 'kana' ? item.kana : item.english}`);
      if (answered) {
        button.disabled = true;
        if (item.id === correct.id) button.classList.add('right');
        if (item.id === chosenId) {
          button.classList.add('flip');
          const block = document.createElement('span'); block.className = 'choice-japanese';
          const kanji = document.createElement('span'); kanji.textContent = item.kanji;
          if (item.kanji !== item.kana) { const reading = document.createElement('small'); reading.textContent = item.kana; block.append(reading); }
          block.append(kanji);
          const definition = document.createElement('span'); definition.className = 'choice-meaning'; definition.textContent = item.english;
          button.append(block, definition);
        } else {
          button.classList.add(item.id === correct.id ? 'right' : 'faded');
          button.textContent = answerMode === 'kana' ? item.kana : item.english;
        }
      } else {
        button.textContent = answerMode === 'kana' ? item.kana : item.english;
        button.addEventListener('click', () => chooseAnswer(item.id));
      }
      el.answerGrid.append(button);
    });
  }
  function chooseAnswer(id) {
    if (!session || answered || !el.resultsOverlay.hidden || !el.levelOverlay.hidden) return;
    answered = true;
    chosenId = id;
    const item = activeItem();
    const isCorrect = id === item.id;
    const p = progressFor(session.key);
    if (isCorrect) {
      session.correct++;
      if (p.mistakes[item.id]) p.mistakes[item.id] = Math.max(0, p.mistakes[item.id] - 1);
    } else {
      session.incorrect++;
      session.missed.push(item);
      p.mistakes[item.id] = (p.mistakes[item.id] || 0) + 1;
    }
    save();
    el.questionCard.classList.add('revealed');
    el.questionDetails.hidden = false;
    el.meaningList.replaceChildren();
    const meanings = item.meanings?.length ? item.meanings : item.english.split(';').map(x => x.trim());
    meanings.forEach(meaning => { const li = document.createElement('li'); li.textContent = meaning; el.meaningList.append(li); });
    el.nextButton.disabled = false;
    el.swipeTip.textContent = 'Swipe atau tekan tombol apa saja untuk lanjut';
    renderQuestion(); renderOptions(); updateCounters();
  }
  function nextQuestion() {
    if (!session || !answered || !el.resultsOverlay.hidden || !el.levelOverlay.hidden) return;
    if (session.index === session.items.length - 1) return finishQuiz();
    session.index++;
    loadQuestion();
  }
  function finishQuiz() {
    if (!session) return;
    const before = levelProgress(session.key);
    const score = pct(session.correct, session.items.length);
    if (session.mode === 'group') {
      const key = `${quizSize}:${session.group}`;
      const progress = progressFor(session.key);
      progress.best[key] = Math.max(score, progress.best[key] || 0);
    }
    save();
    const after = levelProgress(session.key);
    el.resultHead.classList.toggle('passed', score >= 70);
    el.resultHeading.textContent = `${score}%`;
    el.resultScore.textContent = `${session.correct} of ${session.items.length} correct`;
    el.resultGroupName.textContent = displayLabel().replace(' Group ', ' · Group ');
    el.resultLevelLabel.textContent = `${levelName(session.key)} progress`;
    el.resultLevelPercent.textContent = `${after}%`;
    el.resultDelta.textContent = `+${Math.max(0, after - before)}%`;
    el.resultProgressBar.style.width = `${after}%`;
    el.retryButton.disabled = session.missed.length === 0;
    el.nextGroupButton.textContent = session.mode === 'group' && session.group < groupCount(session.key) ? 'Next Group →' : 'Group 1 →';
    el.resultsOverlay.hidden = false;
    el.resultHeading.focus?.();
  }
  function bindEvents() {
    el.openLevels.addEventListener('click', () => openDrawer());
    el.closeLevels.addEventListener('click', closeDrawer);
    el.levelOverlay.querySelector('[data-close-levels]').addEventListener('click', closeDrawer);
    el.backToLevels.addEventListener('click', () => { drawerLevelKey = null; renderDrawer(); });
    el.categoryTabs.addEventListener('click', e => {
      const button = e.target.closest('[data-category]'); if (!button) return;
      drawerCategory = button.dataset.category; drawerLevelKey = null; renderDrawer();
    });
    el.sizeTabs.addEventListener('click', e => {
      const button = e.target.closest('[data-size]'); if (!button) return;
      quizSize = button.dataset.size; save(); renderGroups();
    });
    el.randomQuiz.addEventListener('click', () => beginQuiz({ key: drawerLevelKey, mode: 'random' }));
    el.weakQuiz.addEventListener('click', () => beginQuiz({ key: drawerLevelKey, mode: 'weak' }));
    el.resetProgress.addEventListener('click', () => {
      if (!drawerLevelKey || !confirm(`Hapus semua progres ${levelName(drawerLevelKey)} di browser ini?`)) return;
      saved.progress ||= {}; delete saved.progress[drawerLevelKey]; save(); renderGroups(); notify('Progres level berhasil direset.');
    });
    document.querySelectorAll('[data-prompt-mode]').forEach(button => button.addEventListener('click', () => changePromptMode(button.dataset.promptMode)));
    document.querySelectorAll('[data-answer-mode]').forEach(button => button.addEventListener('click', () => changeAnswerMode(button.dataset.answerMode)));
    el.nextButton.addEventListener('click', nextQuestion);
    el.nextGroupButton.addEventListener('click', () => beginQuiz({ key: session.key, mode: 'group', group: (session.mode === 'group' && session.group < groupCount(session.key)) ? session.group + 1 : 1 }));
    el.restartButton.addEventListener('click', () => beginQuiz({ key: session.key, mode: session.mode === 'retry' ? 'group' : session.mode, group: session.group }));
    el.retryButton.addEventListener('click', () => beginQuiz({ key: session.key, mode: 'retry', group: session.group, customItems: session.missed }));
    el.randomAgainButton.addEventListener('click', () => beginQuiz({ key: session.key, mode: 'random' }));
    el.chooseLevelButton.addEventListener('click', () => { el.resultsOverlay.hidden = true; openDrawer(getLevel(session.key)?.category); });
    document.addEventListener('keydown', e => {
      if (!el.levelOverlay.hidden) { if (e.key === 'Escape') closeDrawer(); return; }
      if (!el.resultsOverlay.hidden || e.altKey || e.metaKey || e.ctrlKey) return;
      if (e.target.matches('button, input, textarea, select')) return;
      if (!session) return;
      if (answered) { e.preventDefault(); nextQuestion(); return; }
      if (/^[1-9]$/.test(e.key)) {
        const target = options[Number(e.key) - 1]; if (target) chooseAnswer(target.id);
      }
    });
    let touchStart = null;
    document.addEventListener('touchstart', e => {
      if (e.touches.length === 1) touchStart = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    }, { passive: true });
    document.addEventListener('touchend', e => {
      if (!touchStart || !answered || !el.levelOverlay.hidden || !el.resultsOverlay.hidden) { touchStart = null; return; }
      const dx = e.changedTouches[0].clientX - touchStart.x;
      const dy = e.changedTouches[0].clientY - touchStart.y;
      if (Math.abs(dx) > 75 && Math.abs(dx) > Math.abs(dy) * 1.3) nextQuestion();
      touchStart = null;
    }, { passive: true });
  }
  async function initialize() {
    await loadData();
    if (!data[activeLevelKey]) activeLevelKey = 'vocabulary_N5';
    bindEvents();
    const level = getLevel(activeLevelKey);
    drawerCategory = level?.category || 'vocabulary';
    beginQuiz({ key: activeLevelKey, mode: 'group', group: 1 });
  }
  initialize().catch(error => { console.error('Jepun Quiz initialization failed', error); notify('Gagal memuat kuis. Coba refresh halaman.'); });
})();
